// KeijiroTube vertex shader with wave animation
in vec4 a_position;
in vec3 a_normal;
in vec4 a_color;
in vec3 a_texcoord0;  // Need z component for radius
in vec4 a_texcoord1;
in vec4 a_tangent;

out vec4 v_color;
out vec3 v_normal;
out vec3 v_tangent;  // Camera-space tangent.
out vec3 v_bitangent;  // Camera-space bitangent.
out vec3 v_position;
out vec2 v_texcoord0;
out vec3 v_light_dir_0;
out vec3 v_light_dir_1;
out float f_fog_coord;

uniform mat4 u_SceneLight_0_matrix;
uniform mat4 u_SceneLight_1_matrix;
uniform vec4 u_time;
uniform bool u_isNewTiltExporter;


void main() {
  vec4 pos = a_position;
  float radius = a_texcoord0.z;
  if (u_isNewTiltExporter && radius <= 0.000001) {
    radius = a_texcoord1.x;
  }

  float wave = sin(a_texcoord0.x - u_time.z);
  float pulse = smoothstep(0.45, 0.5, clamp(wave, 0.0, 1.0));

  if (u_isNewTiltExporter) {
    // The baked mesh already contains the pose from bake time (_Time.z == 2).
    float bakedWave = sin(a_texcoord0.x - 2.0);
    float bakedPulse = smoothstep(0.45, 0.5, clamp(bakedWave, 0.0, 1.0));
    pos.xyz -= (pulse - bakedPulse) * radius * a_normal;
  } else {
    pos.xyz -= pulse * radius * a_normal;
  }

  gl_Position = projectionMatrix * modelViewMatrix * pos;
  f_fog_coord = gl_Position.z;
  // Transform normal and tangent to view space
  vec3 normal = normalize(normalMatrix * a_normal);
  vec3 tangent = normalize(normalMatrix * a_tangent.xyz);

  // Compute bitangent using cross product and handedness
  vec3 bitangent = cross(normal, tangent) * a_tangent.w;

  v_normal = normal;
  v_tangent = tangent;
  v_bitangent = bitangent;
  v_position = (modelViewMatrix * pos).xyz;
  v_light_dir_0 = mat3(u_SceneLight_0_matrix) * vec3(0, 0, 1);
  v_light_dir_1 = mat3(u_SceneLight_1_matrix) * vec3(0, 0, 1);
  v_color = a_color;
  v_texcoord0 = a_texcoord0.xy;
}
